:root {
  --np-background: #ffffff;
  --np-foreground: #09090b;

  --np-primary: #18181b;
  --np-primary-foreground: #fafafa;

  --np-secondary: #f4f4f5;
  --np-secondary-foreground: #18181b;

  --np-muted: #f4f4f5;

  --np-border: #e4e4e7;

  --np-ring: #a1a1aa;

  --np-destructive: #dc2626;
  --np-destructive-foreground: #fafafa;
}

/* Dark theme: system preference, overridable with a .dark class */

@media (prefers-color-scheme: dark) {
  :root:not(.light) {
    --np-background: #09090b;
    --np-foreground: #fafafa;

    --np-primary: #fafafa;
    --np-primary-foreground: #18181b;

    --np-secondary: #27272a;
    --np-secondary-foreground: #fafafa;

    --np-muted: #27272a;

    --np-border: #27272a;

    --np-ring: #52525b;

    --np-destructive: #dc2626;
    --np-destructive-foreground: #fafafa;
  }
}

.dark {
  --np-background: #09090b;
  --np-foreground: #fafafa;

  --np-primary: #fafafa;
  --np-primary-foreground: #18181b;

  --np-secondary: #27272a;
  --np-secondary-foreground: #fafafa;

  --np-muted: #27272a;

  --np-border: #27272a;

  --np-ring: #52525b;

  --np-destructive: #dc2626;
  --np-destructive-foreground: #fafafa;
}

/* Base */

.np-button {
  --np-button-bg: var(--np-primary);
  --np-button-fg: var(--np-primary-foreground);
  --np-button-border: transparent;
  --np-button-hover-bg: color-mix(
    in oklch,
    var(--np-primary),
    var(--np-foreground) 20%
  );

  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  gap: 0.375rem;

  height: 2rem;
  padding: 0 0.625rem;

  border: 1px solid var(--np-button-border);
  border-radius: 0.5rem;

  background: var(--np-button-bg);
  background-clip: padding-box;
  color: var(--np-button-fg);

  font: inherit;
  font-size: 0.875rem;
  font-weight: 500;
  line-height: 1;

  white-space: nowrap;
  text-decoration: none;
  user-select: none;

  cursor: pointer;

  transition:
    background-color 150ms ease,
    color 150ms ease,
    border-color 150ms ease,
    box-shadow 150ms ease,
    transform 100ms ease;

  outline: none;
}

.np-button:hover {
  background-color: var(--np-button-hover-bg);
}

.np-button:focus-visible {
  border-color: var(--np-ring);

  box-shadow: 0 0 0 3px color-mix(in oklch, var(--np-ring), transparent 50%);
}

.np-button:active {
  transform: translateY(1px);
}

.np-button[aria-invalid='true'] {
  border-color: var(--np-destructive);

  box-shadow: 0 0 0 3px
    color-mix(in oklch, var(--np-destructive), transparent 80%);
}

.np-button svg {
  width: 1rem;
  height: 1rem;

  flex-shrink: 0;
  pointer-events: none;
}

.np-button svg:not([class]) {
  width: 1rem;
  height: 1rem;
}

/* Variants */

.np-button[data-variant='outline'] {
  --np-button-bg: var(--np-background);
  --np-button-fg: var(--np-foreground);
  --np-button-border: var(--np-border);

  background-color: var(--np-background);
  color: var(--np-foreground);
}

.np-button[data-variant='outline']:hover,
.np-button[data-variant='outline'][aria-expanded='true'] {
  background-color: var(--np-muted);
  color: var(--np-foreground);
}

.np-button[data-variant='secondary'] {
  --np-button-bg: var(--np-secondary);
  --np-button-fg: var(--np-secondary-foreground);

  background-color: var(--np-secondary);
  color: var(--np-secondary-foreground);
}

.np-button[data-variant='secondary']:hover {
  background-color: color-mix(
    in oklch,
    var(--np-secondary),
    var(--np-foreground) 5%
  );
}

.np-button[data-variant='ghost'] {
  --np-button-bg: transparent;
  --np-button-fg: var(--np-foreground);

  background-color: transparent;
  color: var(--np-foreground);
}

.np-button[data-variant='ghost']:hover,
.np-button[data-variant='ghost'][aria-expanded='true'] {
  background-color: var(--np-muted);
}

.np-button[data-variant='destructive'] {
  --np-button-bg: color-mix(in oklch, var(--np-destructive), transparent 90%);
  --np-button-fg: var(--np-destructive);

  background-color: var(--np-button-bg);
  color: var(--np-button-fg);
}

.np-button[data-variant='destructive']:hover {
  background-color: color-mix(in oklch, var(--np-destructive), transparent 80%);
}

.np-button[data-variant='destructive']:focus-visible {
  border-color: color-mix(in oklch, var(--np-destructive), transparent 60%);

  box-shadow: 0 0 0 3px
    color-mix(in oklch, var(--np-destructive), transparent 80%);
}

/* Sizes */

.np-button[data-size='xs'] {
  height: 1.5rem;
  gap: 0.25rem;
  padding: 0 0.5rem;

  border-radius: 0.375rem;

  font-size: 0.75rem;
}

.np-button[data-size='sm'] {
  height: 1.75rem;
  gap: 0.25rem;
  padding: 0 0.625rem;

  font-size: 0.8rem;
}

.np-button[data-size='lg'] {
  height: 2.25rem;
  gap: 0.375rem;
  padding: 0 0.625rem;
}

.np-button[data-size='icon'] {
  width: 2rem;
  height: 2rem;
  padding: 0;
}

.np-button[data-size='icon-xs'] {
  width: 1.5rem;
  height: 1.5rem;
  padding: 0;

  border-radius: 0.375rem;
}

.np-button[data-size='icon-sm'] {
  width: 1.75rem;
  height: 1.75rem;
  padding: 0;
}

.np-button[data-size='icon-lg'] {
  width: 2.25rem;
  height: 2.25rem;
  padding: 0;
}

/* States */

.np-button:disabled,
.np-button[data-state='disabled'] {
  pointer-events: none;
  opacity: 0.5;
}

.np-button[data-state='loading'] {
  position: relative;

  pointer-events: none;
  opacity: 0.8;
  cursor: progress;
}

.np-button[data-state='loading']::before {
  content: '';

  width: 1em;
  height: 1em;
  flex-shrink: 0;

  border: 2px solid currentColor;
  border-right-color: transparent;
  border-radius: 50%;

  animation: np-button-spin 0.6s linear infinite;
}

@keyframes np-button-spin {
  to {
    transform: rotate(360deg);
  }
}

@media (prefers-reduced-motion: reduce) {
  .np-button[data-state='loading']::before {
    animation-duration: 1.2s;
  }
}
